SOURCES = {'agent/message_content.py': '_NON_TEXT_PART_TYPES = {"image", "image_url", "input_image", "audio", "input_audio"}\n\n_TEXT_KEYS = ("text", "content", "input_text", "output_text", "summary_text")\n\ndef _field(value: Any, key: str) -> Any:\n    return value.get(key) if isinstance(value, Mapping) else getattr(value, key, None)\n\ndef _text_from_part(part: Any) -> str:\n    if part is None:\n        return ""\n    if isinstance(part, str):\n        return part\n    if str(_field(part, "type") or "").strip().lower() in _NON_TEXT_PART_TYPES:\n        return ""\n    for key in _TEXT_KEYS:\n        text = _field(part, key)\n        if isinstance(text, str):\n            return text\n    return ""\n\ndef flatten_message_text(content: Any, *, sep: str = "\\n") -> str:\n    """Return the visible text from common chat/Responses message content shapes."""\n    if content is None:\n        return ""\n    if isinstance(content, str):\n        return content\n    if isinstance(content, list):\n        return sep.join(chunk for chunk in map(_text_from_part, content) if chunk)\n    text = _text_from_part(content)\n    if text:\n        return text\n    try:\n        return str(content)\n    except Exception:\n        return ""\n', 'agent/turn_context.py': 'def _memory_query_text(original_user_message: Any) -> str:\n    """Semantic text of the turn for memory queries: a multimodal (list) turn carries its text\n    in parts, so keying off ``isinstance(str)`` collapsed it to ``""`` and ``is_trivial_prompt``\n    skipped prefetch entirely. An image-only turn still flattens to ``""`` (trivial)."""\n    if isinstance(original_user_message, (str, list)):\n        return flatten_message_text(original_user_message)\n    return ""\n', 'agent/codex_responses_adapter.py': '_TEXT_PART_TYPES = {"text", "input_text", "output_text"}\n\n_IMAGE_PART_TYPES = {"image_url", "input_image"}\n\ndef _nonempty_str(value: Any) -> TypeGuard[str]:\n    return isinstance(value, str) and bool(value)\n\ndef _str_or_empty(value: Any) -> str:\n    return "" if value is None else str(value)\n\ndef _part_type(part: dict[str, Any]) -> str:\n    return str(part.get("type") or "").strip().lower()\n\ndef _iter_content_parts(content: list) -> Iterator[tuple[str, Any]]:\n    """Yield ``("text", str)`` / ``("image", part)`` for recognized chat parts."""\n    for part in content:\n        if isinstance(part, str) and part:\n            yield "text", part\n        elif isinstance(part, dict):\n            ptype = _part_type(part)\n            if ptype in _TEXT_PART_TYPES and _nonempty_str(part.get("text")):\n                yield "text", part["text"]\n            elif ptype in _IMAGE_PART_TYPES:\n                yield "image", part\n\ndef _summarize_user_message_for_log(content: Any, *, sep: str = " ") -> str:\n    """Flatten message content to plain text: text parts joined with ``sep`` (``" "`` for logs; ``"\\\\n"`` for memory\n    providers feeding regexes), images → ``[N image(s)]`` marker, ``""`` for None, ``str(content)`` for other scalars."""\n    if not isinstance(content, list):\n        try:\n            return _str_or_empty(content)\n        except Exception:\n            return ""\n    parts = list(_iter_content_parts(content))\n    text_bits = [payload for kind, payload in parts if kind == "text"]\n    image_count = len(parts) - len(text_bits)\n    note = f"[{image_count} image{\'s\' if image_count != 1 else \'\'}]" if image_count else ""\n    return " ".join(bit for bit in (note, sep.join(text_bits).strip()) if bit)\n', 'agent/image_routing.py': 'def build_native_content_parts(\n    user_text: str,\n    image_paths: list[str],\n    image_urls: Optional[list[str]] = None,\n) -> tuple[list[dict[str, Any]], list[str]]:\n    """Build an OpenAI-style ``content`` list for a user turn.\n\n    Local paths become base64 ``data:`` URLs; remote URLs pass through verbatim.\n    When any image attaches, one text part combines the caption (or a neutral\n    default) with a ``[Image attached at: <path>]`` / ``[Image attached: <url>]``\n    hint per image — a string handle for tools taking an image path/URL, mirroring\n    ``Runner._enrich_message_with_vision``. Returns ``(content_parts, skipped)``;\n    ``skipped`` holds unreadable local paths (URLs are never skipped).\n    """\n    skipped: list[str] = []\n    attached: list[tuple[str, str]] = []  # (url, hint)\n    for raw_path in image_paths:\n        p = Path(raw_path)\n        data_url = _file_to_data_url(p) if p.exists() and p.is_file() else None\n        if data_url:\n            attached.append((data_url, f"[Image attached at: {raw_path}]"))\n        else:\n            skipped.append(str(raw_path))\n    attached += [(u, f"[Image attached: {u}]") for u in ((u or "").strip() for u in image_urls or []) if u]\n\n    text = (user_text or "").strip()\n    if not attached:\n        return ([{"type": "text", "text": text}] if text else []), skipped\n    combined_text = f"{text or \'What do you see in this image?\'}\\n\\n" + "\\n".join(h for _, h in attached)\n    image_parts = [{"type": "image_url", "image_url": {"url": u}} for u, _ in attached]\n    return [{"type": "text", "text": combined_text}, *image_parts], skipped\n', 'gateway/session_api_media.py': 'def restore_api_images(content, media):\n    """The transient content keeps its pixels; its text gains the validated committed reference\n    per inline image (remote URLs keep their address) so the persisted user row records what\n    was seen, exactly like native image turns."""\n    from gateway.session_ingress_media import restore_native_media\n    paths = iter(restore_native_media(media))\n    hints = []\n    for url in _image_urls(content):\n        if _data_url_bytes(url) is not None:\n            hints.append(f\'[Image attached at: {next(paths)}]\')\n        else:\n            hints.append(f\'[Image attached: {url}]\')\n    if not hints:\n        return content\n    parts = [dict(part) for part in content]\n    text = next((part for part in parts if part.get(\'type\') == \'text\'), None)\n    if text is None:\n        text = {\'type\': \'text\', \'text\': \'What do you see in this image?\'}\n        parts.insert(0, text)\n    text[\'text\'] = text[\'text\'] + \'\\n\\n\' + \'\\n\'.join(hints)\n    return parts\n'}


